        LANGUAGE_WRAPPER = 'A point $P$ is chosen in the interior of a tetrahedron $T$. The four planes passing through $P$ and parallel to the faces of $T$ define a partition of $T$. This partition includes four small tetrahedra at the corners of $T$ and four parallelepipeds, one opposite each vertex. The volumes of these four parallelepipeds are ${v1}$, ${v2}$, ${v3}$, and ${v4}$. Find the volume of the tetrahedron $T$.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        def generator(rng):
    # These sets of integers `a_i` have a sum divisible by 6, ensuring an integer final volume.
    # They are chosen to produce non-trivial parallelepiped volumes.
    possible_a_sets = [
        [2, 3, 5, 8],  # sum = 18
        [2, 3, 6, 7],  # sum = 18
        [2, 4, 5, 7],  # sum = 18
        [3, 4, 5, 6],  # sum = 18
        [1, 5, 8, 10], # sum = 24
        [2, 5, 7, 10], # sum = 24
        [3, 4, 7, 10], # sum = 24
        [4, 5, 6, 9]   # sum = 24
    ]

    a = rng.choice(possible_a_sets)

    # The volumes of the parallelepipeds are products of the other three `a_i` values.
    # This construction is based on the derivation V = (sum(a_i))^3 / 6.
    v = [
        a[1] * a[2] * a[3],
        a[0] * a[2] * a[3],
        a[0] * a[1] * a[3],
        a[0] * a[1] * a[2]
    ]
    rng.shuffle(v)

    return {
        'v1': v[0],
        'v2': v[1],
        'v3': v[2],
        'v4': v[3]
    }

        from fractions import Fraction

def verifier(assign):
    v = [assign['v1'], assign['v2'], assign['v3'], assign['v4']]

    # Volumes must be positive integers.
    if not all(isinstance(x, int) and x > 0 for x in v):
        return False, None

    # For this problem's structure, the parallelepiped volumes should be distinct.
    if len(set(v)) != 4:
        return False, None

    prod_v = 1
    for val in v:
        prod_v *= val

    sum_inv_v = sum(Fraction(1, val) for val in v)

    # The volume of an n-simplex is given by V = (1/n!) * (product of parallelotope volumes) * (sum of reciprocal volumes)^n
    # For a tetrahedron, n=3.
    volume = Fraction(1, 6) * prod_v * (sum_inv_v**3)

    # The generator is designed to produce an integer volume.
    if volume.denominator != 1:
        return False, None

    answer = int(volume)

    # Enforce difficulty constraints.
    if any(x < 20 for x in v) or answer < 500:
        return False, None

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
